    dan_hdr_new(&l->h, dl_LLTporozhdenieu2eMesto_destroy);
    l->len = n;
    l->cap = n < 4 ? 4 : n;
    l->items = dan_alloc((size_t)l->cap * sizeof(dl_LTporozhdenieu2eMesto*));
    for (int64_t i = 0; i < n; i++) l->items[i] = dl_LTporozhdenieu2eMesto_share(src[i]);
