/* все части словаря - в одном блоке памяти (одно выделение вместо пяти): отпечатки,
   таблица поиска, ключи, значения и признаки «запись есть» на cap записей */
static void dm_Dib_block(dm_Dib *d, int64_t cap) {
    int64_t s = 8;
    while (s < 2 * cap) s *= 2;
    size_t c = (size_t)cap, kb = (sizeof(int64_t) * c + 7) & ~(size_t)7, vb = (sizeof(bool) * c + 7) & ~(size_t)7;
    char *b = dan_alloc(8 * c + 8 * (size_t)s + kb + vb + c);
    d->hashes = (uint64_t *)(void *)b;
    d->index = (int64_t *)(void *)(b + 8 * c);
    d->keys = (int64_t *)(void *)(b + 8 * c + 8 * (size_t)s);
    d->vals = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb);
    d->alive = (bool *)(void *)(b + 8 * c + 8 * (size_t)s + kb + vb);
    d->cap = cap;
    d->slots = s;
}
static void dm_Dib_reindex(dm_Dib *d) {
    int64_t s = d->slots;
    for (int64_t i = 0; i < s; i++) d->index[i] = -1;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        int64_t p = (int64_t)(d->hashes[e] & (uint64_t)(s - 1));
        while (d->index[p] >= 0) p = (p + 1) & (s - 1);
        d->index[p] = e;
    }
}
static int64_t dm_Dib_lookup(const dm_Dib *d, int64_t k, uint64_t h) {
    if (!d->slots) return -1;
    for (int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));; p = (p + 1) & (d->slots - 1)) {
        int64_t e = d->index[p];
        if (e < 0) return -1;
        if (d->alive[e] && d->hashes[e] == h) { int64_t a = d->keys[e], b = k; if ((a == b)) return e; }
    }
}
static void dm_Dib_grow(dm_Dib *d) {   /* убирает удалённые записи и увеличивает таблицу */
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    int64_t *keys = d->keys; bool *vals = d->vals; uint64_t *hashes = d->hashes; bool *alive = d->alive;
    int64_t n = d->n;
    dm_Dib_block(d, cap);
    for (int64_t e = 0; e < n; e++) {
        if (!alive[e]) continue;
        d->keys[m] = keys[e]; d->vals[m] = vals[e]; d->hashes[m] = hashes[e]; d->alive[m] = true; m++;
    }
    dan_free(hashes);
    d->n = m;
    dm_Dib_reindex(d);
}
static void dm_Dib_put(dm_Dib *d, int64_t k, bool v) {
    uint64_t h = dan_hash_i(k);
    int64_t e = dm_Dib_lookup(d, k, h);
    if (e >= 0) { bool old = d->vals[e]; d->vals[e] = DAN_ID(v); DAN_NOREL(old); (void)old; return; }
    if (d->n == d->cap) dm_Dib_grow(d);
    e = d->n++;
    d->keys[e] = DAN_ID(k); d->vals[e] = DAN_ID(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* запись в новый словарь значений, которые уже учтены (копия для задачи) */
static void dm_Dib_put_raw(dm_Dib *d, int64_t k, bool v) {
    uint64_t h = dan_hash_i(k);
    if (d->n == d->cap) dm_Dib_grow(d);
    int64_t e = d->n++;
    d->keys[e] = k; d->vals[e] = v; d->hashes[e] = h; d->alive[e] = true; d->len++;
    int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
    while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
    d->index[p] = e;
}
/* место значения по ключу; если ключа нет, запись создаётся со значением v (одно обращение
   вместо получить и записать) */
static bool *dm_Dib_slot(dm_Dib *d, int64_t k, bool v) {
    uint64_t h = dan_hash_i(k);
    int64_t e = dm_Dib_lookup(d, k, h);
    if (e < 0) {
        if (d->n == d->cap) dm_Dib_grow(d);
        e = d->n++;
        d->keys[e] = DAN_ID(k); d->vals[e] = DAN_ID(v); d->hashes[e] = h; d->alive[e] = true; d->len++;
        int64_t p = (int64_t)(h & (uint64_t)(d->slots - 1));
        while (d->index[p] >= 0) p = (p + 1) & (d->slots - 1);
        d->index[p] = e;
    }
    return &d->vals[e];
}
static dm_Dib *dm_Dib_from(int64_t n, const int64_t *ks, const bool *vs) {
    dm_Dib *d = dm_Dib_new();
    for (int64_t i = 0; i < n; i++) dm_Dib_put(d, ks[i], vs[i]);
    return d;
}
static bool dm_Dib_get(const dm_Dib *d, int64_t k, int line) {
    int64_t e = dm_Dib_lookup(d, k, dan_hash_i(k));
    if (e < 0) dan_key_error(dan_int_to_str(k), line);
    return d->vals[e];
}
static bool *dm_Dib_at(dm_Dib *d, int64_t k, int line) {
    int64_t e = dm_Dib_lookup(d, k, dan_hash_i(k));
    if (e < 0) dan_key_error(dan_int_to_str(k), line);
    return &d->vals[e];
}
static bool dm_Dib_contains(const dm_Dib *d, int64_t k) { return dm_Dib_lookup(d, k, dan_hash_i(k)) >= 0; }

static do_b dm_Dib_find(const dm_Dib *d, int64_t k) {
    int64_t e = dm_Dib_lookup(d, k, dan_hash_i(k));
    return e < 0 ? do_b_none() : do_b_some(d->vals[e]);
}
static bool dm_Dib_get_or(const dm_Dib *d, int64_t k, bool v) {
    int64_t e = dm_Dib_lookup(d, k, dan_hash_i(k));
    return e < 0 ? v : d->vals[e];
}
static void dm_Dib_remove(dm_Dib *d, int64_t k) {
    int64_t e = dm_Dib_lookup(d, k, dan_hash_i(k));
    if (e >= 0) { d->alive[e] = false; d->len--; DAN_NOREL(d->keys[e]); DAN_NOREL(d->vals[e]); }
}
static dl_Li *dm_Dib_keys(const dm_Dib *d) {
    dl_Li *r = dl_Li_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Li_push(r, d->keys[e]);
    return r;
}
static dl_Lb *dm_Dib_values(const dm_Dib *d) {
    dl_Lb *r = dl_Lb_from(0, NULL);
    for (int64_t e = 0; e < d->n; e++) if (d->alive[e]) dl_Lb_push(r, d->vals[e]);
    return r;
}
/* копия для изменения: записи переносятся вместе с готовыми отпечатками (без повторного
   вычисления), место - с запасом вдвое, чтобы следующая запись не перестраивала таблицу */
static dm_Dib *dm_Dib_copy(const dm_Dib *d) {
    dm_Dib *r = dm_Dib_new();
    if (d->len == 0) return r;
    int64_t cap = d->len * 2 < 8 ? 8 : d->len * 2, m = 0;
    dm_Dib_block(r, cap);
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        r->keys[m] = DAN_ID(d->keys[e]); r->vals[m] = DAN_ID(d->vals[e]); r->hashes[m] = d->hashes[e]; r->alive[m] = true; m++;
    }
    r->n = r->len = m;
    dm_Dib_reindex(r);
    return r;
}
static dm_Dib *dm_Dib_mut(dm_Dib **pp) {
    dm_Dib *d = *pp;
    if (d->h.rc > 1) { dm_Dib *r = dm_Dib_copy(d); r->h.rc = 1; d->h.rc--; *pp = r; return r; }
    return d;
}
static dan_str dm_Dib_str(const dm_Dib *d) {
    dan_buf b = { NULL, 0, 0 };
    dan_buf_add(&b, "{");
    bool first = true;
    for (int64_t e = 0; e < d->n; e++) {
        if (!d->alive[e]) continue;
        if (!first) dan_buf_add(&b, ", ");
        first = false;
        dan_buf_add(&b, dan_int_to_str(d->keys[e]));
        dan_buf_add(&b, ": ");
        dan_buf_add(&b, dan_bool_to_str(d->vals[e]));
    }
    dan_buf_add(&b, "}");
    return dan_buf_str(&b);
}
static void dm_Dib_write(const dm_Dib *d) { fputs(dm_Dib_str(d), stdout); }


static bool dm_Dib_eq(const dm_Dib *x, const dm_Dib *y) {
    if (x->len != y->len) return false;
    for (int64_t e = 0; e < x->n; e++) {
        if (!x->alive[e]) continue;
        int64_t f = dm_Dib_lookup(y, x->keys[e], x->hashes[e]);
        if (f < 0) return false;
        bool a = x->vals[e]; bool b = y->vals[f];
        if (!((a == b))) return false;
    }
    return true;
}


